const compactView=()=>window.matchMedia?.('(max-width:900px)').matches;
let pnLastTransitionKey='';
function transitionRender(){
 const key=[st.route,st.tab,st.league?.league_id||''].join('|');
 const change=key!==pnLastTransitionKey;
 pnLastTransitionKey=key;
 const update=()=>{render();if(change)window.scrollTo(0,0)};
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){update();return}
 if(change&&typeof document.startViewTransition==='function'){
   document.startViewTransition(update);
 }else{
   update();
   if(change)document.querySelector('.content')?.animate(
     [{opacity:.55,transform:'translate3d(0,7px,0)'},{opacity:1,transform:'translate3d(0,0,0)'}],
     {duration:210,easing:'cubic-bezier(.22,1,.36,1)'}
   );
 }
}
document.addEventListener('keydown',event=>{
 const dialog=$('.player-profile');if(!dialog)return;
 if(event.key==='Escape'){event.preventDefault();closePlayerProfile();return}
 if(event.key!=='Tab')return;
 const focusable=[...dialog.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])')]
   .filter(x=>x.getClientRects().length);
 if(!focusable.length)return;
 const first=focusable[0],last=focusable[focusable.length-1];
 if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}
 else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}
});
function bindProfile(){
  $('[data-a="closeProfile"]')?.addEventListener('click',closePlayerProfile);
  $('[data-profile-backdrop]')?.addEventListener('click',e=>{if(e.target===e.currentTarget)closePlayerProfile()});
}
function mountPlayerProfile(){
  $('[data-profile-backdrop]')?.remove();
  const html=playerProfile();
  if(!html)return;
  $('#app')?.insertAdjacentHTML('beforeend',html);
  bindProfile();
}
function refreshPlayerProfile(){
 if(!st.profile)return;
 const old=$('[data-profile-backdrop]');
 if(!old){mountPlayerProfile();return}
 const previousScroll=old.querySelector('.player-profile')?.scrollTop||0;
 old.outerHTML=playerProfile();
 const sheet=$('.player-profile');
 if(sheet){sheet.classList.add('pn-no-entrance');sheet.scrollTop=previousScroll}
 bindProfile();
}
function closePlayerProfile(){
  const sheet=$('.player-profile'),backdrop=$('[data-profile-backdrop]');
  const finish=()=>{st.profile=null;st.profileRoster=null;backdrop?.remove();if(pnPreviouslyFocused?.isConnected)pnPreviouslyFocused.focus({preventScroll:true});pnPreviouslyFocused=null};
  if(!sheet||window.matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return}
  const mobile=compactView();
  const anim=sheet.animate(
    [{opacity:1,transform:'translate3d(0,0,0)'},{opacity:.45,transform:mobile?'translate3d(0,8px,0)':'translate3d(7px,0,0)'}],
    {duration:210,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'}
  );
  backdrop?.animate([{opacity:1},{opacity:0}],{duration:190,fill:'forwards'});
  anim.onfinish=finish;
}

