function playerProfile(){const id=st.profile;if(!id)return'';const p=st.players?.[id]||{},dst=isDstId(id,p),m=model(id,p),e=resolveModel(id,p),b=e?.base||{},rank=n(field(b,['dynasty_rank','model_dynasty_rank','overall_dynasty_rank'])),y3=n(field(b,['year3_fppg'])),career=n(field(b,['dynasty_career_projected_points','career_projected_points'])),ageV=n(p?.age??field(b,['age'])),gp=m.avgGames,avgSub=m.avgSource==='actual'?`Actual · ${gp||0} GP`:m.avgSource==='projected'?'Projected baseline':'Unavailable',pos=String(p?.position||field(b,['position'])||'').toUpperCase(),stats=[];if(pos==='QB'){stats.push(['Pass Att',seasonStat(id,'pass_att')],['Pass Yds',seasonStat(id,'pass_yd',['pass_yds'])],['Pass TD',seasonStat(id,'pass_td')],['Rush Att',seasonStat(id,'rush_att')])}else if(pos==='RB'){stats.push(['Carries',seasonStat(id,'rush_att')],['Rush Yds',seasonStat(id,'rush_yd',['rush_yds'])],['Targets',seasonStat(id,'rec_tgt',['targets'])],['Receptions',seasonStat(id,'rec')])}else if(['WR','TE'].includes(pos)){stats.push(['Targets',seasonStat(id,'rec_tgt',['targets'])],['Receptions',seasonStat(id,'rec')],['Rec Yds',seasonStat(id,'rec_yd',['rec_yds'])],['Rec TD',seasonStat(id,'rec_td')])}const notes=profileAnalysis(id,p,m),av=m.availability||availabilityInfo(id,p,st.week,1),news=st.playerNews.get(String(id)),projectionSub=m.projectionWasOverridden&&m.rawProjection!=null?`Availability override · base ${f(m.rawProjection)}`:av.factor<1?`Availability ${Math.round(av.factor*100)}% applied`:'Model projection',newsHtml=(!news||news?.loading)?'<div class="news-loading">Loading recent player reports…</div>':news?.articles?.length?news.articles.map(a=>`<a class="news-card" ${a.url?`href="${esc(a.url)}" target="_blank" rel="noopener"`:''}><div class="news-meta">${esc(newsDate(a.published))}${news.source?` · ${esc(news.source)}`:''}</div><strong>${esc(a.headline)}</strong>${a.description?`<p>${esc(String(a.description).slice(0,220))}${String(a.description).length>220?'…':''}</p>`:''}</a>`).join(''):'<div class="muted small">No recent player-specific reports were returned for this player.</div>';return`<div class="profile-backdrop" data-profile-backdrop><aside class="player-profile" role="dialog" aria-modal="true" aria-label="${esc(pname(id))} player profile" style="${teamStyle(p?.team||field(b,['team']))}"><div class="profile-grabber"></div><div class="profile-head"><span class="profile-portrait"><img class="profile-image ${dst?'dst-logo':''}" src="${assetImage(id,p)}" alt="" onerror="this.style.visibility='hidden'"></span><div class="profile-title"><div class="eyebrow">Player analysis</div><h2>${esc(pname(id))}</h2><div class="player-meta">${esc(pos||'—')} · ${esc(p?.team||field(b,['team'])||'FA')}${ageV!=null?` · Age ${f(ageV,0)}`:''}</div><div class="player-opp">${esc(m.opp||'Matchup unavailable')}</div>${availabilityChip(av)}</div><button class="profile-close" data-a="closeProfile" aria-label="Close player profile">×</button></div><div class="profile-metrics"><div class="profile-metric ${av.factor<=0?'availability-zero':''}"><span>Week ${st.week}</span><strong>${f(m.projection)}</strong><small>${esc(projectionSub)}</small></div><div class="profile-metric"><span>Season PPG</span><strong>${f(m.avg)}</strong><small>${esc(avgSub)}</small></div><div class="profile-metric"><span>Range</span><strong>${f(m.floor)}–${f(m.ceiling)}</strong><small>Floor–ceiling</small></div><div class="profile-metric"><span>Dynasty</span><strong>${m.dynasty!=null?fi(m.dynasty):'—'}</strong><small>${rank!=null?`Rank #${fi(rank)}`:'Model value'}</small></div></div>${(av.label||av.factor<1||av.body||av.notes)?`<div class="availability-panel ${av.factor<=0?'bad':av.factor<1?'warn':''}"><div><span>Availability</span><strong>${esc(av.label||`${Math.round(av.factor*100)}% available`)}</strong></div>${av.body?`<div><span>Injury</span><strong>${esc(av.body)}</strong></div>`:''}<p>${esc(av.reason)}</p>${av.notes?`<small>${esc(av.notes)}</small>`:''}</div>`:''}${stats.some(([,v])=>v!=null)?`<div class="profile-section"><div class="profile-section-title">Current season production</div><div class="profile-stat-grid">${stats.map(([k,v])=>`<div><span>${k}</span><strong>${v==null?'—':f(v,0)}</strong></div>`).join('')}</div></div>`:''}<div class="profile-section"><div class="profile-section-title">Model context</div><div class="profile-context-grid"><div><span>Confidence</span><strong>${esc(conf(m.confidence))}</strong></div><div><span>Availability</span><strong>${Math.round(av.factor*100)}%</strong></div><div><span>Year 3 PPG</span><strong>${f(y3)}</strong></div><div><span>Career projected pts</span><strong>${career!=null?fi(career):'—'}</strong></div></div></div><div class="profile-section"><div class="profile-section-title">Why this projection</div><div class="analysis-list">${notes.length?notes.map(x=>`<div class="analysis-item"><span>•</span><p>${esc(x)}</p></div>`).join(''):'<div class="muted">Not enough current data for analysis yet.</div>'}</div></div>${!dst?`<div class="profile-section"><div class="profile-section-title">Recent player news</div><div class="news-list">${newsHtml}</div></div>`:''}<div class="profile-source">Availability uses fresh Sleeper roster/injury status plus the Powers-Newlon Model's player-week availability factor. Definitive current-week IR/Out/PUP/NFI/suspension status overrides the weekly projection to 0. Recent reports are shown for context and do not independently change the number unless they are reflected in structured availability data.</div></aside></div>`}

function dstProjectionValue(row){const x=dstStats(row),scoring=st.league?.scoring_settings||{};let total=0,matched=0;for(const[k,w0]of Object.entries(scoring)){const sv=maybeNum(x[k]),w=maybeNum(w0);if(sv!=null&&w!=null){total+=sv*w;matched++}}if(matched)return total;for(const k of ['pts_ppr','pts_half_ppr','pts_std','fantasy_points','projection']){const v=maybeNum(x[k]);if(v!=null)return v}return null}
async function loadDstProjections(week=st.week){st.dstProjections=new Map;if(!week)return;const urls=[`https://api.sleeper.app/v1/projections/nfl/regular/${st.season}/${week}?position[]=DEF&order_by=pts_ppr`,`https://api.sleeper.app/projections/nfl/${st.season}/${week}?season_type=regular&position[]=DEF&order_by=pts_ppr`,`https://api.sleeper.com/projections/nfl/${st.season}/${week}?season_type=regular&position=DEF&order_by=pts_ppr`];for(const url of urls){const data=await liveJson(url,null);const entries=Array.isArray(data)?data.map((r,i)=>[r?.player_id||r?.team||String(i),r]):data&&typeof data==='object'?Object.entries(data):[];if(!entries.length)continue;for(const[key,row]of entries){const x=dstStats(row),raw=x.player_id||x.team||key,c=teamCode(raw);if(NFL_TEAM_META[c]){st.dstProjections.set(String(raw),row);st.dstProjections.set(c,row)}}if(st.dstProjections.size)break}}
function dstModel(id,p=st.players?.[id],week=st.week){const c=dstTeam(id,p),row=st.dstProjections.get(String(id))||st.dstProjections.get(c)||null,v=dstProjectionValue(row);return{projection:v,pregame:v,floor:null,ceiling:null,avg:null,dynasty:null,confidence:'Sleeper',opp:field(dstStats(row),['opponent','opp']),matched:true,hasWeek:v!=null,source:'Sleeper'}}
async function loadLeagues(user=st.username,season=st.season){st.loading=true;render();const u=await liveJson(`${S}/user/${encodeURIComponent(user)}`);if(!u?.user_id){st.loading=false;st.error='Sleeper user not found.';render();return}st.user=u;st.leagues=await liveJson(`${S}/user/${u.user_id}/leagues/nfl/${season}`,[])||[];st.username=user;st.season=+season;st.error='';localStorage.fm_username=user;localStorage.fm_season=season;st.loading=false;render()}
async function refreshLeague(notify=true){const id=st.league?.league_id;if(!id)return;st.loading=true;render();await Promise.all([players(notify),nflState(),loadSeasonStats(notify)]);await loadDstProjections(st.week);const [league,users,rosters,matchups,picks,drafts]=await Promise.all([liveJson(`${S}/league/${id}`,st.league),liveJson(`${S}/league/${id}/users`,[]),liveJson(`${S}/league/${id}/rosters`,[]),liveJson(`${S}/league/${id}/matchups/${st.week}`,[]),liveJson(`${S}/league/${id}/traded_picks`,[]),liveJson(`${S}/league/${id}/drafts`,[])]);if(league)st.league=league;st.users=users||[];st.rosters=rosters||[];st.matchups=matchups||[];st.picks=picks||[];st.drafts=drafts||[];st.team=rby(st.team)?.roster_id||me()?.roster_id||st.rosters[0]?.roster_id;st.tradeA=rby(st.tradeA)?.roster_id||me()?.roster_id||st.rosters[0]?.roster_id;st.tradeB=rby(st.tradeB)?.roster_id||st.rosters.find(r=>r.roster_id!==st.tradeA)?.roster_id;st.assetsA=new Set;st.assetsB=new Set;st.loading=false;st.leagueFetchedAt=Date.now();auditProjections();render();if(notify)toast('League and current-season stats refreshed from Sleeper.')}
async function openLeague(id){st.league=st.leagues.find(l=>String(l.league_id)===String(id))||await liveJson(`${S}/league/${id}`);if(!st.league)return toast('Could not load league.');st.tab='home';localStorage.fm_league_id=id;localStorage.fm_league_tab='home';await refreshLeague(false)}
async function setWeek(w){st.week=+w;await loadDstProjections(st.week);if(st.league)st.matchups=await liveJson(`${S}/league/${st.league.league_id}/matchups/${w}`,[])||[];auditProjections();render()}
function slots(){return(st.league?.roster_positions||[]).filter(s=>!['BN','IR','TAXI'].includes(String(s).toUpperCase()))}
function eligible(slot,p){const s=String(slot).toUpperCase(),pos=String(p?.position||'').toUpperCase();if(s===pos)return true;if(['FLEX','RB_WR_TE','WRRB_FLEX','REC_FLEX'].includes(s))return['RB','WR','TE'].includes(pos);if(['SUPER_FLEX','SUPERFLEX','OP'].includes(s))return['QB','RB','WR','TE'].includes(pos);if(s==='WR_TE')return['WR','TE'].includes(pos);return false}
function optimal(r){const ids=(r?.players||[]).filter(id=>st.players?.[id]),ss=[...slots()].sort((a,b)=>/FLEX|OP/.test(a)-/FLEX|OP/.test(b)),used=new Set,map=new Map;for(const s of ss){const c=ids.filter(id=>!used.has(id)&&eligible(s,st.players[id])).map(id=>({id,v:model(id).projection??-999})).sort((a,b)=>b.v-a.v)[0];if(c){used.add(c.id);map.set(c.id,s)}}return map}
function mi(id){return st.matchups.find(m=>+m.roster_id===+id)}
function oppId(id){const a=mi(id);return st.matchups.find(m=>m.matchup_id===a?.matchup_id&&+m.roster_id!==+id)?.roster_id}
function rproj(r){let total=0,ok=false;for(const id of optimal(r).keys()){const v=model(id).projection;if(v!=null){total+=v;ok=true}}return ok?total:null}
function ppg(r){const s=r?.settings||{},pts=n(s.fpts,0)+n(s.fpts_decimal,0)/100,g=n(s.wins,0)+n(s.losses,0)+n(s.ties,0);return g?pts/g:null}
function age(id){return n(st.players?.[id]?.age)}
function avgAge(r){const a=(r?.players||[]).map(age).filter(x=>x!=null);return a.length?a.reduce((x,y)=>x+y,0)/a.length:null}
function dval(id){return model(id).dynasty||0}
function rdyn(r){return(r?.players||[]).reduce((a,id)=>a+dval(id),0)}
function strength(r){const x={QB:[],RB:[],WR:[],TE:[]};for(const id of r?.players||[]){const p=st.players?.[id];if(x[p?.position])x[p.position].push(model(id).projection||0)};Object.values(x).forEach(a=>a.sort((a,b)=>b-a));return{QB:x.QB[0]||0,RB:(x.RB[0]||0)+(x.RB[1]||0),WR:(x.WR[0]||0)+(x.WR[1]||0)+(x.WR[2]||0),TE:x.TE[0]||0}}
function need(r){const s=strength(r),avg={};for(const p of Object.keys(s))avg[p]=st.rosters.reduce((a,x)=>a+strength(x)[p],0)/(st.rosters.length||1);return Object.keys(s).sort((a,b)=>s[a]/(avg[a]||1)-s[b]/(avg[b]||1))[0]||'—'}
function windowOf(r){const a=avgAge(r),v=ppg(r),all=st.rosters.map(ppg).filter(x=>x!=null).sort((a,b)=>a-b),med=all[Math.floor(all.length/2)];if(v!=null&&med!=null&&v>=med&&(a==null||a<28))return'Contender';if(a!=null&&a<25.5&&(v==null||med==null||v<med))return'Rebuilding';return'Fringe'}
function draftComplete(y=st.season){return st.drafts.some(d=>+d.season===+y&&String(d.status||'').toLowerCase()==='complete')}
function pickAssets(id){const rounds=+(st.league?.settings?.draft_rounds||4),out=[],first=draftComplete(st.season)?st.season+1:st.season;for(let y=first;y<=st.season+3;y++)for(let r=1;r<=rounds;r++){let owner=id;const t=[...st.picks].reverse().find(p=>+p.roster_id===+id&&+p.season===y&&+p.round===r);if(t?.owner_id)owner=t.owner_id;if(+owner===+id)out.push({season:y,round:r,original:id,key:`pick:${y}:${r}:${id}`})}for(const p of st.picks)if(+p.owner_id===+id&&+p.roster_id!==+id&&+p.season>=first){const q={season:+p.season,round:+p.round,original:+p.roster_id,key:`pick:${p.season}:${p.round}:${p.roster_id}`};if(!out.some(x=>x.key===q.key))out.push(q)}return out.sort((a,b)=>a.season-b.season||a.round-b.round)}
function rosterPF(r){const s=r?.settings||{};return n(s.fpts,0)+n(s.fpts_decimal,0)/100}
function currentDraftSlots(){const a=[...st.rosters].sort((a,b)=>{const sa=a.settings||{},sb=b.settings||{};return n(sa.wins,0)-n(sb.wins,0)||n(sa.ties,0)-n(sb.ties,0)||rosterPF(a)-rosterPF(b)||+a.roster_id-+b.roster_id});return new Map(a.map((r,i)=>[+r.roster_id,i+1]))}
function metricSlots(fn){const a=st.rosters.map(r=>({id:+r.roster_id,v:n(fn(r))})).sort((a,b)=>(a.v??-Infinity)-(b.v??-Infinity)||a.id-b.id);return new Map(a.map((x,i)=>[x.id,i+1]))}
function powerDraftSlot(id){const teams=Math.max(1,st.rosters.length),mid=(teams+1)/2,dyn=metricSlots(r=>rdyn(r)),proj=metricSlots(r=>rproj(r)),form=metricSlots(r=>ppg(r));const d=dyn.get(+id)??mid,q=proj.get(+id)??mid,g=form.get(+id)??mid,week=Math.max(1,+st.nflWeek||1),formW=Math.min(.30,.10+Math.max(0,week-1)*.02),dynW=.52-formW/2,projW=1-dynW-formW;return dynW*d+projW*q+formW*g}
function draftOutlook(p){const teams=Math.max(1,st.rosters.length),mid=(teams+1)/2,current=currentDraftSlots().get(+p.original)??mid,power=powerDraftSlot(p.original),week=Math.max(1,+st.nflWeek||1),progress=Math.min(1,Math.max(0,(week-1)/11)),standW=.35+.50*progress,horizon=Math.max(0,+p.season-+st.season-1),regress=Math.min(.45,horizon*.18);let projected=standW*current+(1-standW)*power;projected=(1-regress)*projected+regress*mid;projected=Math.max(1,Math.min(teams,projected));const spread=Math.max(1,Math.round((1-progress)*teams*.22+horizon*.75)),lo=Math.max(1,Math.round(projected-spread)),hi=Math.min(teams,Math.round(projected+spread));return{teams,current:Math.round(current),power,projected,slot:Math.max(1,Math.min(teams,Math.round(projected))),lo,hi}}
function pickCode(p,slot){return`${+p.round}.${String(Math.max(1,Math.round(slot))).padStart(2,'0')}`}
function pickBaseVal(p){const v=st.pickValues.get(`${+p.season}:${+p.round}`);if(v!=null)return v;return({1:4200,2:1800,3:800,4:350}[p.round]||100)*Math.pow(.92,Math.max(0,p.season-st.season-1))}
function pickSlotMultiplier(round,slot,teams){if(teams<=1)return 1;const steep=({1:.70,2:.50,3:.35,4:.25}[+round]||.20),pos=(Math.max(1,Math.min(teams,slot))-1)/(teams-1);return Math.exp(steep*(.5-pos))}
