function picks(r){const p=pickAssets(r.roster_id);return p.length?`<div class="pick-grid">${p.map(x=>{const o=pickMeta(x);return`<div class="pick"><strong>${x.season} ${ord(x.round)} · ${o.proj}</strong><div class="muted small">${x.original===r.roster_id?'Own pick':`via ${esc(tname(x.original))}`}</div><div class="muted small">${esc(o.label)} · ${esc(o.detail)}</div><div class="small" style="color:var(--accent);margin-top:5px">Value ${fi(pickVal(x))}</div></div>`}).join('')}</div>`:'<div class="empty">No future picks found.</div>'}
function teamHome(r,own=true){if(!r)return'<div class="empty empty-plain">No roster found for this user.</div>';const opt=optimal(r),starts=(r.starters||[]).filter(x=>x&&x!=='0'),set=new Set(starts),bench=(r.players||[]).filter(x=>!set.has(x));return`<div class="team-heading"><div><span class="kicker">${own?'Your roster':'Team view'}</span><h1 class="page-title">${esc(tname(r.roster_id))}</h1></div><div class="week-control">${weekSel()}</div></div>${matchup(r)}<section class="roster-section"><div class="section-head"><h2>Starters</h2><span class="section-note">Model slot recommendations</span></div>${rosterTable(r,starts,opt)}</section><section class="roster-section"><div class="section-head"><h2>Bench</h2></div>${rosterTable(r,bench,opt)}</section><section class="roster-section"><div class="section-head"><h2>Draft capital</h2></div>${picks(r)}</section>`}
